useEffect(() => {
  // 1단계: 조건부 종료 (Guard Clause)
  if (!running) return 

  // 2단계: 타이머 등록 및 백그라운드 위임
  const id = setInterval(() => {
    // 2-1단계 (내부 계층): 1초마다 브라우저가 독립적으로 실행
    setSeconds((s) => s + 1)
  }, 1000)

  // 3단계: 클린업(해제) 함수 예약
  return () => clearInterval(id) 
}, [running])


