import React, { useState } from 'react';

export default function BailoutExample() {
const [box, setBox] = useState({ count: 0 });

// ❌ 잘못된 방법 (안 바뀜)
const handleWrongUpdate = () => {
box.count += 1; // 기존 객체의 내부 값만 수정
setBox(box); // React: "이전 box 객체와 메모리 주소(참조)가 같네? 무시하자(Bailout)."
};

// ✅ 올바른 방법 (바뀜)
const handleRightUpdate = () => {
// 스프레드 연산자(...)로 완전히 새로운 객체를 생성하여 전달
setBox({ ...box, count: box.count + 1 });
// React: "새로운 객체(새로운 참조)가 들어왔네! 화면을 다시 그려야겠다."
};

return (
<div style={{ padding: '20px' }}>
<h2>현재 카운트: {box.count}</h2>

<button onClick={handleWrongUpdate} style={{ marginRight: '10px' }}>
❌ 참조 유지 (안 바뀜)
</button>

<button onClick={handleRightUpdate}>
✅ 새 참조 생성 (바뀜)
</button>
</div>
);
}

